    if (this.originalPosition) {
      this.originalPosition.parent.insertBefore(card, this.originalPosition.next)
      this.originalPosition = null
    }
  }

  #numberOf(card) {
    return card.querySelector(".card__link").pathname.split("/").pop()
  }
}
